constraints:
1 ≤ M, N ≤ 10^{2}

expected time complexity: O(M*N*(N +M))
expected auxiliary space: O(M*N)

standard_solution_code:
import sys

class Solution:

	def get(self, m, n, dp):
		if m == n:
			return 1
		if dp[m][n] != -1:
			return dp[m][n]
		ans = sys.maxsize
		for i in range(1, m // 2 + 1):
			ans = min(ans, self.get(i, n, dp) + self.get(m - i, n, dp))
		for i in range(1, n // 2 + 1):
			ans = min(ans, self.get(m, i, dp) + self.get(m, n - i, dp))
		dp[m][n] = ans
		return dp[m][n]

	def minCut(self, m, n):
		dp = []
		for i in range(0, m + 1):
			dp.append([-1] * (n + 1))
		return self.get(m, n, dp)
